//! Wire-surface catalog for the `provider::openrouter::*` functions — the
//! single source of truth for each function's id, registration description,
//! and schemars-derived request/response schemas.
//!
//! Golden-tested in `tests/schemas.rs`; keep in lockstep with
//! [`crate::register::register_provider`]. Schema generation MUST mirror
//! iii-sdk's internal `json_schema_for` (`SchemaSettings::draft07()` on the
//! handler's request/response types) so a catalog snapshot pins exactly what
//! registration emits.
//!
//! No `count_tokens` surface: OpenRouter exposes no pre-request tokenizer
//! endpoint, and one local tokenizer cannot honestly meter models spanning
//! every vendor's vocabulary — the router reports `no_token_counter` and the
//! harness falls back to its own estimate.

use llm_router::types::router::{
    ProviderAbortRequest, ProviderAbortResponse, ProviderReadyAck, ProviderStreamInput,
    ProviderStreamOutput, RefreshModelsRequest, RefreshModelsResponse, RouterReadyEvent,
};

pub const STREAM_ID: &str = "provider::openrouter::stream";
pub const STREAM_DESC: &str =
    "Stream an OpenRouter chat completion: resolve credentials, call the upstream \
     Chat Completions API, and relay AssistantMessageEvent frames to writer_ref.";

pub const ABORT_ID: &str = "provider::openrouter::abort";
pub const ABORT_DESC: &str = "Cancel the in-flight upstream stream for a request_id \
     (router::abort fan-out), stopping billed generation immediately.";

pub const REFRESH_MODELS_ID: &str = "provider::openrouter::refresh_models";
pub const REFRESH_MODELS_DESC: &str =
    "Refresh the OpenRouter catalog slice from GET /api/v1/models — ids, context \
     windows, pricing, and capabilities all come from the live listing — and \
     reconcile it through the router; returns the model count written.";

pub const ON_ROUTER_READY_ID: &str = "provider::openrouter::on_router_ready";
pub const ON_ROUTER_READY_DESC: &str =
    "Internal: router::ready subscriber that re-declares this provider and refreshes its catalog.";

/// One function's complete agent-facing wire surface: id, registration
/// description, and the schemars-derived request/response schemas.
pub struct FunctionSpec {
    pub function_id: &'static str,
    pub description: &'static str,
    pub request_schema: schemars::schema::RootSchema,
    pub response_schema: schemars::schema::RootSchema,
}

fn schema_of<T: schemars::JsonSchema>() -> schemars::schema::RootSchema {
    schemars::r#gen::SchemaSettings::draft07()
        .into_generator()
        .into_root_schema_for::<T>()
}

fn spec<Req, Resp>(function_id: &'static str, description: &'static str) -> FunctionSpec
where
    Req: schemars::JsonSchema,
    Resp: schemars::JsonSchema,
{
    FunctionSpec {
        function_id,
        description,
        request_schema: schema_of::<Req>(),
        response_schema: schema_of::<Resp>(),
    }
}

/// The full wire-surface catalog, in registration order. Golden-tested in
/// `tests/schemas.rs`; keep in lockstep with `register::register_provider`.
pub fn catalog() -> Vec<FunctionSpec> {
    vec![
        spec::<ProviderStreamInput, ProviderStreamOutput>(STREAM_ID, STREAM_DESC),
        spec::<ProviderAbortRequest, ProviderAbortResponse>(ABORT_ID, ABORT_DESC),
        spec::<RefreshModelsRequest, RefreshModelsResponse>(REFRESH_MODELS_ID, REFRESH_MODELS_DESC),
        spec::<RouterReadyEvent, ProviderReadyAck>(ON_ROUTER_READY_ID, ON_ROUTER_READY_DESC),
    ]
}
//! The `provider::openrouter::stream` iii function (spec § Provider stream
//! contract): write AssistantMessageEvent frames as JSON text messages into
//! the router-owned channel, terminal done/error last, then close.
use crate::catalog::upstream_id;
use crate::config::config_from_resolve;
use crate::errors::classify_bus_error;
use crate::request::{build_body, build_headers, BodyArgs};
use crate::sse::synthetic_error_event;
use crate::upstream::{spawn_upstream, UpstreamArgs};
use crate::{router_client, state};
use futures::future::BoxFuture;
use iii_sdk::errors::Error;
use iii_sdk::IIIClient;
use llm_router::channels::open_sink;
use llm_router::chat::relay::FrameSink;
use llm_router::provider_scaffold::aborts::{AbortGuard, StreamAborts};
use llm_router::provider_scaffold::cache::derive_affinity_id;
use llm_router::provider_scaffold::pump::pump_abortable;
use llm_router::types::events::{AssistantMessageEvent, ErrorKind};
use llm_router::types::model::{Model, ThinkingLevel};
use llm_router::types::router::{ProviderStreamInput, ProviderStreamOutput};
use std::time::Duration;
use tokio::sync::mpsc;

/// Heartbeat cadence while the upstream is silent (spec: at least every 30s).
pub const PING_INTERVAL: Duration = Duration::from_secs(30);

fn resolve_session_id(
    provider_options: Option<&serde_json::Value>,
    session_id: Option<&str>,
) -> Option<String> {
    provider_options
        .and_then(|options| options.get("session_id"))
        .and_then(serde_json::Value::as_str)
        .filter(|key| !key.trim().is_empty())
        .map(str::to_string)
        .or_else(|| session_id.and_then(derive_affinity_id))
}

pub fn make_stream(
    iii: IIIClient,
    http: reqwest::Client,
    aborts: StreamAborts,
) -> impl Fn(ProviderStreamInput) -> BoxFuture<'static, Result<ProviderStreamOutput, Error>>
       + Send
       + Sync
       + 'static {
    move |input: ProviderStreamInput| {
        let (iii, http, aborts) = (iii.clone(), http.clone(), aborts.clone());
        Box::pin(async move {
            // Register BEFORE the first await: an abort landing while the sink
            // opens must latch, not hit an unknown id. The RAII guard
            // deregisters on every exit — early returns and an executor
            // cancelling this future mid-await alike.
            let abort_reg = input
                .resolution_key
                .as_ref()
                .map(|rid| aborts.register(rid));
            let sink = open_sink(&iii, &input.writer_ref).await?;
            run_stream_call(&iii, http, abort_reg.as_ref(), input, sink.as_ref()).await;
            sink.close();
            // ProviderStreamOutput (spec § stream contract)
            Ok(ProviderStreamOutput { ok: true })
        })
    }
}

/// Resolve a requested thinking level against the model's advertised efforts
/// (OpenRouter's `reasoning.supported_efforts`, carried on the catalog
/// record). Preference ladders step DOWN, never up, so a request can only get
/// less reasoning than asked, not more. No advertised list → send the first
/// candidate as-is (OpenRouter drops parameters a model does not support).
pub fn resolve_reasoning_effort(level: ThinkingLevel, meta: Option<&Model>) -> Option<String> {
    // `none` disables reasoning (use-cases/reasoning-tokens); only sent when
    // the model advertises it, since `reasoning.mandatory` models reject it.
    if level == ThinkingLevel::Off {
        return meta
            .filter(|m| m.supports_thinking_off != Some(false))
            .and_then(|m| m.reasoning_efforts.as_ref())
            .filter(|efforts| efforts.iter().any(|e| e.effort == "none"))
            .map(|_| "none".to_string());
    }
    let candidates: &[&str] = match level {
        ThinkingLevel::Off => &[],
        ThinkingLevel::Minimal => &["minimal", "low"],
        ThinkingLevel::Low => &["low", "minimal"],
        ThinkingLevel::Medium => &["medium", "low"],
        ThinkingLevel::High => &["high", "medium"],
        ThinkingLevel::Xhigh => &["xhigh", "high", "medium"],
    };
    let advertised = meta.and_then(|m| m.reasoning_efforts.as_ref());
    match advertised {
        Some(efforts) => candidates
            .iter()
            .find(|c| efforts.iter().any(|e| e.effort == **c))
            .map(|c| c.to_string()),
        None => Some(candidates[0].to_string()),
    }
}

fn send_event(sink: &dyn FrameSink, ev: &AssistantMessageEvent) -> Result<(), ()> {
    let frame = serde_json::to_string(ev).expect("serializable event");
    sink.send(&frame).map_err(|_| ())
}

async fn run_stream_call(
    iii: &IIIClient,
    http: reqwest::Client,
    abort_reg: Option<&AbortGuard>,
    input: ProviderStreamInput,
    sink: &dyn FrameSink,
) {
    let model = input.model.clone();
    let mut warnings = Vec::new();

    let token = state::load_token(iii).await;
    let resolved = match router_client::resolve(iii, token.as_deref()).await {
        Ok(r) => r,
        Err(e) => {
            let _ = send_event(
                sink,
                &synthetic_error_event(
                    &format!("router::provider::resolve failed: {e}"),
                    &model,
                    classify_bus_error(&e),
                ),
            );
            return;
        }
    };
    let cfg = match config_from_resolve(&model, input.max_output_tokens, &resolved) {
        Ok(c) => c,
        Err(_) => {
            let _ = send_event(
                sink,
