    }
    fn closer(&self) -> Arc<dyn Fn() + Send + Sync> {
        let flag = self.close_flag.clone();
        let cancel = self.cancel.clone();
        Arc::new(move || {
            flag.store(true, Ordering::SeqCst);
            cancel.notify_waiters();
        })
    }
    fn close(&self) {
        (self.closer())();
    }
}

